import { useDatePicker } from '@dreadnought/react/logic';
export function Example() {
  const picker = useDatePicker({ defaultValue: '2026-10-12' });
  return <input aria-label="Дата" value={picker.draft[0]} onChange={event => picker.setDraft(0, event.target.value)} onBlur={picker.confirm} />;
}
